+        // 覆盖（不支持的等级由供应商报错，接受）；不透传官方 compat（其 thinkingFormat
+        // 等按官方 API 行为描述，对中转站不适用）
+        thinkingLevelMap: id !== "" ? STANDARD_THINKING_LEVEL_MAP : undefined,
       };
     })
     .filter((m) => m.id !== "");
 }
